import{_ as t,o as c,c as o,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"04 — Gói Truyền thông, Chiến dịch & Yêu cầu Nội dung (Media Package, Media Campaign & Content Request)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/04-media-package-campaign.md","filePath":"ba/04-media-package-campaign.md"}'),n={name:"ba/04-media-package-campaign.md"};function a(i,e,g,l,h,r){return c(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="_04-—-goi-truyen-thong-chien-dich-yeu-cau-noi-dung-media-package-media-campaign-content-request" tabindex="-1">04 — Gói Truyền thông, Chiến dịch &amp; Yêu cầu Nội dung (Media Package, Media Campaign &amp; Content Request) <a class="header-anchor" href="#_04-—-goi-truyen-thong-chien-dich-yeu-cau-noi-dung-media-package-media-campaign-content-request" aria-label="Permalink to &quot;04 — Gói Truyền thông, Chiến dịch &amp; Yêu cầu Nội dung (Media Package, Media Campaign &amp; Content Request)&quot;">​</a></h1><p>&gt; Navigation: <a href="./README.html">← BA Overview &amp; Hub</a> · <a href="./03-agency-workspace.html">← 03 - Agency &amp; Workspace</a> · <a href="./05-content-task-workflow.html">Tiếp: 05 - Content &amp; Task Workflow →</a> &gt; &gt; <strong>Phạm vi FR chuẩn</strong>: <strong>Mục <code>3.5 Media Package &amp; Media Campaign</code> — 13 FR (<code>3.5.1</code> – <code>3.5.13</code>)</strong> | <code>UC-040</code> – <code>UC-052</code> · Use Cases chi tiết: <a href="./use-cases/03-media-package-campaign.html">use-cases/03-media-package-campaign.md</a> · Đặc tả SRS: <a href="./../feature/srs/04-media-package-campaign/README.html">04-media-package-campaign</a>. &gt; Đã đồng bộ với <strong>8 loại Dịch vụ / Công việc chuẩn (<code>PackageServiceType</code> ↔ <code>TaskType</code>)</strong>, luồng <code>Manager-led Package &amp; Campaign Approval</code>, và luồng <strong>Chiến dịch Cá nhân không cần Gói dịch vụ (<code>workspaceMode = &quot;PERSONAL&quot;</code>)</strong>.</p><hr><h2 id="_1-bang-tong-hop-13-yeu-cau-chuc-nang-chuan-3-5-1-–-3-5-13" tabindex="-1">1. Bảng Tổng hợp 13 Yêu cầu Chức năng Chuẩn (<code>3.5.1</code> – <code>3.5.13</code>) <a class="header-anchor" href="#_1-bang-tong-hop-13-yeu-cau-chuc-nang-chuan-3-5-1-–-3-5-13" aria-label="Permalink to &quot;1. Bảng Tổng hợp 13 Yêu cầu Chức năng Chuẩn (`3.5.1` – `3.5.13`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (Atomic CRUD FR)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.5.1</code></strong></td><td style="text-align:center;"><code>UC-040</code></td><td style="text-align:left;"><strong>Create Media Package</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Tạo mới hoặc tùy chỉnh Gói truyền thông mẫu (<code>MediaPackage</code>) ở cấp <code>Agency</code> với danh mục các hạng mục dịch vụ, số lượng, đơn vị chuẩn, đơn giá và điều khoản.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.2</code></strong></td><td style="text-align:center;"><code>UC-041</code></td><td style="text-align:left;"><strong>View Template Media Package</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Xem danh sách và chi tiết các Gói truyền thông mẫu của <code>Agency</code> hoặc bảng đề xuất gói gắn với <code>Workspace</code> (hỗ trợ xuất PDF đề xuất đa ngôn ngữ &amp; chia sẻ link công khai cho <code>Guest</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.5.3</code></strong></td><td style="text-align:center;"><code>UC-042</code></td><td style="text-align:left;"><strong>Request Media Package</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Đề xuất và đàm phán điều chỉnh gói truyền thông (<code>WorkspaceMediaPackage</code> — giá, thời lượng, số lượng hạng mục) qua từng vòng cho đến khi thống nhất (<code>BR-25</code>, <code>BR-26</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.5.4</code></strong></td><td style="text-align:center;"><code>UC-043</code></td><td style="text-align:left;"><strong>Approve Media Package</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Phê duyệt chốt gói truyền thông khi cả hai bên (<code>Agency</code> và <code>Client</code>) đồng thuận (<code>status = APPROVED</code>, <code>BR-26</code>, <code>BR-27</code>) để mở khóa bước lập Chiến dịch truyền thông.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.5</code></strong></td><td style="text-align:center;"><code>UC-044</code></td><td style="text-align:left;"><strong>Create Media Campaign</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Khởi tạo Kế hoạch Chiến dịch truyền thông (<code>MediaCampaign</code>): đặt tên, mục tiêu, lộ trình <code>Start</code>/<code>End Date</code> và danh sách các hạng mục bài viết dự kiến (<code>workItems</code>, <code>BR-27</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.5.6</code></strong></td><td style="text-align:center;"><code>UC-045</code></td><td style="text-align:left;"><strong>View Media Campaign</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem chi tiết kế hoạch chiến dịch, lịch sử phiên bản, luồng phản hồi và <strong>Lịch trình Chiến dịch (<code>CampaignTimelineGrid</code>)</strong> kèm trạng thái từng Subtask (<code>BR-27</code>, <code>BR-28</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.5.7</code></strong></td><td style="text-align:center;"><code>UC-046</code></td><td style="text-align:left;"><strong>Update Media Campaign</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Cập nhật nội dung Kế hoạch Chiến dịch truyền thông và gửi phản hồi điều chỉnh khi chiến dịch đang ở trạng thái nháp / chờ duyệt (<code>BR-27</code>–<code>BR-30</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.5.8</code></strong></td><td style="text-align:center;"><code>UC-047</code></td><td style="text-align:left;"><strong>Approve Media Campaign</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Phê duyệt và kích hoạt triển khai Chiến dịch (<code>ACTIVE</code>): tự động đẩy toàn bộ hạng mục công việc vào Task Backlog kèm bộ <strong>Subtask theo vai trò chuẩn (<code>TaskCatalog</code>, <code>BR-29</code>)</strong>.</td></tr><tr><td style="text-align:center;"><strong><code>3.5.9</code></strong></td><td style="text-align:center;"><code>UC-048</code></td><td style="text-align:left;"><strong>Complete Media Campaign</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Nghiệm thu và hoàn tất Chiến dịch truyền thông (<code>status = COMPLETED</code>), đồng thời tự động hủy (<code>CANCELLED</code>) các yêu cầu phát sinh còn treo <code>PENDING</code> thuộc chiến dịch đó (<code>BR-30</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.5.10</code></strong></td><td style="text-align:center;"><code>UC-049</code></td><td style="text-align:left;"><strong>Create Content Request</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Tạo yêu cầu nội dung bổ sung/phát sinh ngoài kế hoạch ban đầu (<code>status = PENDING</code>, <code>BR-31</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.5.11</code></strong></td><td style="text-align:center;"><code>UC-050</code></td><td style="text-align:left;"><strong>Track Request Status</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Theo dõi và điều phối trạng thái Yêu cầu nội dung (<code>PENDING → IN_PROGRESS → ACCEPTED / DENIED</code>); khi chuyển sang <code>ACCEPTED</code>, tự động sinh <code>Task</code> đẩy vào Backlog (<code>BR-31</code>, <code>BR-33</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.5.12</code></strong></td><td style="text-align:center;"><code>UC-051</code></td><td style="text-align:left;"><strong>Update Request</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Chỉnh sửa nội dung của Yêu cầu phát sinh khi còn ở trạng thái <code>PENDING</code>; khóa chỉnh sửa ngay khi đã chuyển sang <code>IN_PROGRESS</code>, <code>ACCEPTED</code> hoặc <code>DENIED</code> (<code>BR-32</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.5.13</code></strong></td><td style="text-align:center;"><code>UC-052</code></td><td style="text-align:left;"><strong>Cancel Request</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Hủy yêu cầu nội dung phát sinh khi đang ở trạng thái <code>PENDING</code> (<code>status = CANCELLED</code>, <code>BR-32</code>).</td></tr></tbody></table><hr><h2 id="_2-anh-xa-8-loai-hang-muc-dich-vu-packageservicetype-sang-8-loai-cong-viec-tasktype" tabindex="-1">2. Ánh xạ 8 Loại Hạng mục Dịch vụ (<code>PackageServiceType</code>) sang 8 Loại Công việc (<code>TaskType</code>) <a class="header-anchor" href="#_2-anh-xa-8-loai-hang-muc-dich-vu-packageservicetype-sang-8-loai-cong-viec-tasktype" aria-label="Permalink to &quot;2. Ánh xạ 8 Loại Hạng mục Dịch vụ (`PackageServiceType`) sang 8 Loại Công việc (`TaskType`)&quot;">​</a></h2><p>Hệ thống chuẩn hóa 8 loại dịch vụ truyền thông trong Gói dịch vụ (<code>PackageOfferingValidator</code> &amp; <code>CampaignPlanValidator</code>), ánh xạ 1-đối-1 sang 8 loại Công việc (<code>TaskType</code>) khi triển khai chiến dịch:</p><table tabindex="0"><thead><tr><th style="text-align:center;">STT</th><th style="text-align:left;"><code>PackageServiceType</code></th><th style="text-align:left;"><code>TaskType</code> sinh ra khi Deploy</th><th style="text-align:center;">Đơn vị chuẩn (<code>Standard Unit</code>)</th><th style="text-align:left;">Số lượng Subtask vai trò tự động sinh (<code>TaskCatalog</code>)</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong><code>CONTENT_POST</code></strong></td><td style="text-align:left;"><code>POST</code></td><td style="text-align:center;"><code>&quot;bài&quot;</code></td><td style="text-align:left;">5 vai trò (<code>POST_RESEARCH</code>, <code>POST_CONTENT</code>, <code>POST_MEDIA</code>, <code>POST_EDITING</code>, <code>POST_PUBLISHING</code>)</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong><code>SHORT_VIDEO</code></strong></td><td style="text-align:left;"><code>SHORT_VIDEO</code></td><td style="text-align:center;"><code>&quot;video&quot;</code></td><td style="text-align:left;">4 vai trò (<code>VIDEO_SCRIPT</code>, <code>VIDEO_SHOOT</code>, <code>VIDEO_EDIT</code>, <code>VIDEO_PUBLISH</code>)</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong><code>SURVEY</code></strong></td><td style="text-align:left;"><code>SURVEY</code></td><td style="text-align:center;"><code>&quot;khảo sát&quot;</code></td><td style="text-align:left;">3 vai trò (<code>SURVEY_DESIGN</code>, <code>SURVEY_DISTRIBUTE</code>, <code>SURVEY_ANALYSIS</code>)</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong><code>EVENT_PLAN</code></strong></td><td style="text-align:left;"><code>EVENT_PLAN</code></td><td style="text-align:center;"><code>&quot;sự kiện&quot;</code></td><td style="text-align:left;">5 vai trò (<code>EVENT_AGENDA</code>, <code>EVENT_LOGISTICS</code>, <code>EVENT_PROMOTION</code>, <code>EVENT_ONSITE</code>, <code>EVENT_REPORT</code>)</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong><code>PRESS_RECOMMENDATION</code></strong></td><td style="text-align:left;"><code>PRESS_RECOMMENDATION</code></td><td style="text-align:center;"><code>&quot;thông cáo&quot;</code></td><td style="text-align:left;">4 vai trò (<code>PRESS_MEDIA_LIST</code>, <code>PRESS_RELEASE</code>, <code>PRESS_PITCHING</code>, <code>PRESS_TRACKING</code>)</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong><code>KOL_BOOKING</code></strong></td><td style="text-align:left;"><code>KOL_BOOKING</code></td><td style="text-align:center;"><code>&quot;KOL&quot;</code></td><td style="text-align:left;">5 vai trò (<code>KOL_SOURCING</code>, <code>KOL_NEGOTIATION</code>, <code>KOL_BRIEF</code>, <code>KOL_CONTENT_REVIEW</code>, <code>KOL_TRACKING</code>)</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong><code>WORKSHOP_SUPPORT</code></strong></td><td style="text-align:left;"><code>WORKSHOP</code></td><td style="text-align:center;"><code>&quot;buổi&quot;</code></td><td style="text-align:left;">5 vai trò (<code>WORKSHOP_PROGRAM</code>, <code>WORKSHOP_SPEAKER</code>, <code>WORKSHOP_LOGISTICS</code>, <code>WORKSHOP_REGISTRATION</code>, <code>WORKSHOP_REPORT</code>)</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong><code>EMAIL_NEWSLETTER</code></strong></td><td style="text-align:left;"><code>EMAIL_NEWSLETTER</code></td><td style="text-align:center;"><code>&quot;bản tin&quot;</code></td><td style="text-align:left;">4 vai trò (<code>EMAIL_CONTENT</code>, <code>EMAIL_DESIGN</code>, <code>EMAIL_SEND</code>, <code>EMAIL_REPORT</code>)</td></tr></tbody></table><p>&gt; <strong>Lưu ý tuân thủ <code>AGENTS.md</code></strong>: Hạng mục <code>LIVESTREAM</code> đã bị loại bỏ hoàn toàn khỏi phạm vi dự án.</p><hr><h2 id="_3-đac-ta-luong-goi-dich-vu-chien-dich-theo-2-che-đo-agency-vs-personal" tabindex="-1">3. Đặc tả Luồng Gói Dịch vụ &amp; Chiến dịch theo 2 Chế độ (<code>AGENCY</code> vs <code>PERSONAL</code>) <a class="header-anchor" href="#_3-đac-ta-luong-goi-dich-vu-chien-dich-theo-2-che-đo-agency-vs-personal" aria-label="Permalink to &quot;3. Đặc tả Luồng Gói Dịch vụ &amp; Chiến dịch theo 2 Chế độ (`AGENCY` vs `PERSONAL`)&quot;">​</a></h2><h3 id="_3-1-trong-che-đo-agency-workspacemode-agency" tabindex="-1">3.1. Trong Chế độ <code>AGENCY</code> (<code>workspaceMode = &quot;AGENCY&quot;</code>) <a class="header-anchor" href="#_3-1-trong-che-đo-agency-workspacemode-agency" aria-label="Permalink to &quot;3.1. Trong Chế độ `AGENCY` (`workspaceMode = &quot;AGENCY&quot;`)&quot;">​</a></h3><ol><li><strong>Giai đoạn 1 — Chốt Gói Truyền thông (<code>3.5.1</code> – <code>3.5.4</code>)</strong>: <ul><li><code>Owner</code> thiết lập danh mục Gói truyền thông mẫu (<code>MediaPackage</code>) tại cấp Agency (<code>3.5.1</code>).</li><li>Tại Workspace của khách hàng, <code>Manager</code> (hoặc <code>Client</code> đề xuất) chọn gói mẫu hoặc tùy chỉnh thành <code>WorkspaceMediaPackage</code> (<code>3.5.3</code>).</li><li>Hỗ trợ xuất bảng báo giá/đề xuất gói ra file <strong>PDF đa ngôn ngữ</strong> (<code>PackageExportRenderer</code>) hoặc tạo link chia sẻ công khai (<code>/s/:token</code>) gửi cho khách hàng xem trước.</li><li>Sau khi thống nhất với khách hàng, <code>Owner</code>/<code>Manager</code> bấm xác nhận chốt gói (<code>3.5.4 Approve Media Package</code> → <code>status = APPROVED</code>), mở khóa bước 2 trên thanh Tiến trình Sidebar.</li></ul></li><li><strong>Giai đoạn 2 — Lập &amp; Triển khai Chiến dịch (<code>3.5.5</code> – <code>3.5.9</code>)</strong>: <ul><li><code>Manager</code> tạo bản nháp Chiến dịch (<code>3.5.5</code>), nhập mục tiêu, ý tưởng và lên danh sách các hạng mục công việc (<code>CampaignWorkItem</code>).</li><li><code>CampaignPlanValidator</code> kiểm tra tổng số lượng từng loại hạng mục không vượt quá hạn mức của <code>WorkspaceMediaPackage</code> đã chốt.</li><li>Khi <code>Manager</code> bấm <strong>Chốt &amp; Triển khai Chiến dịch (<code>3.5.8</code> / <code>deploy</code>)</strong>: <ul><li>Chiến dịch chuyển sang <code>ACTIVE</code>.</li><li><code>CampaignTaskStore.draftTask</code> tự động sinh các <code>TaskDocument</code> cha trong MongoDB, đồng thời <strong>sinh sẵn bộ Subtask theo vai trò chuẩn (<code>TaskCatalog</code>)</strong> cho từng Task (mặc định <code>status = TODO</code>, <code>dueDate</code> = hạn của Task cha, chờ <code>Manager</code> gán người phụ trách).</li></ul></li><li>Trong suốt chiến dịch, tất cả các bên theo dõi tiến độ trên <code>CampaignTimelineGrid</code> (<code>3.5.6</code>), nơi hiển thị trực quan từng Task, các Subtask con, cờ <strong>Trễ hạn (<code>Overdue</code>)</strong> và cờ <strong>Chờ Client duyệt (<code>Awaiting Client</code>)</strong>.</li></ul></li></ol><h3 id="_3-2-trong-che-đo-personal-workspacemode-personal" tabindex="-1">3.2. Trong Chế độ <code>PERSONAL</code> (<code>workspaceMode = &quot;PERSONAL&quot;</code>) <a class="header-anchor" href="#_3-2-trong-che-đo-personal-workspacemode-personal" aria-label="Permalink to &quot;3.2. Trong Chế độ `PERSONAL` (`workspaceMode = &quot;PERSONAL&quot;`)&quot;">​</a></h3><p>Khi người dùng làm việc trong Không gian Cá nhân hoặc Nhóm bài tập (<code>workspaceMode = &quot;PERSONAL&quot;</code>):</p><ol><li><strong>Không bắt buộc Gói dịch vụ (<code>Package-less Workflow</code>)</strong>: <ul><li>Bước <code>1. Gói dịch vụ</code> được ẩn khỏi thanh Tiến trình Sidebar.</li><li>Nếu người dùng vào trang <strong>Chiến dịch (<code>/workspaces/:id/campaigns</code>)</strong> để lập kế hoạch dài hạn (<code>3.5.5</code> – <code>3.5.8</code>), Backend tự động khởi tạo ngầm một <code>WorkspaceMediaPackage</code> khung nội bộ không giới hạn trần số lượng, cho phép người dùng cá nhân tự do thêm bất kỳ số lượng hạng mục nào trong 8 loại <code>TaskType</code> và bấm <code>Deploy</code> ngay lập tức.</li><li>Mọi Task sinh ra từ chiến dịch cá nhân mặc định có <code>requiresClientApproval = false</code> và tự gán cho chủ không gian nếu chưa chọn người khác.</li></ul></li><li><strong>Làm việc không cần Chiến dịch (<code>Standalone Task Bypass</code>)</strong>: <ul><li>Người dùng cá nhân thậm chí không cần vào trang Chiến dịch mà có thể bấm <strong>&quot;+ Tạo công việc mới&quot;</strong> ngay tại trang Công việc (<code>/workspaces/:id/tasks</code>) hoặc từ <strong>Bệ phóng Sáng tạo Cá nhân (<code>Personal Quick Launchpad</code>)</strong> trên Dashboard để tạo trực tiếp 1 công việc lẻ (hệ thống tự gắn vào chiến dịch cá nhân mặc định chạy ngầm).</li></ul></li></ol><hr><h2 id="_4-đac-ta-luong-yeu-cau-noi-dung-cua-khach-hang-3-5-10-–-3-5-13" tabindex="-1">4. Đặc tả Luồng Yêu cầu Nội dung của Khách hàng (<code>3.5.10</code> – <code>3.5.13</code>) <a class="header-anchor" href="#_4-đac-ta-luong-yeu-cau-noi-dung-cua-khach-hang-3-5-10-–-3-5-13" aria-label="Permalink to &quot;4. Đặc tả Luồng Yêu cầu Nội dung của Khách hàng (`3.5.10` – `3.5.13`)&quot;">​</a></h2><p>Luồng <code>Content Request</code> phục vụ riêng cho tương tác giữa <code>Client</code> và <code>Manager</code> trong các Workspace có <code>workspaceMode = &quot;AGENCY&quot;</code>:</p><ol><li><strong><code>3.5.10 Create Content Request</code> (<code>Client</code>)</strong>: <ul><li>Từ <code>Client Portal</code> (<code>/workspaces/:id/portal</code>), <code>Client</code> gửi yêu cầu làm thêm hoặc điều chỉnh nội dung (nhập tiêu đề, loại nội dung mong muốn, mô tả yêu cầu, hạn mong muốn và tệp đính kèm). Bản ghi mới có <code>status = PENDING</code>.</li></ul></li><li><strong><code>3.5.11 Track Request Status</code> (<code>Owner</code>, <code>Manager</code>, <code>Client</code>)</strong>: <ul><li>Theo dõi và điều phối trạng thái của từng yêu cầu qua 4 trạng thái chuẩn: <code>PENDING -&gt; IN_PROGRESS -&gt; ACCEPTED</code> (hoặc <code>DENIED</code>). Khi phía Agency (<code>Owner</code>/<code>Manager</code>) chuyển sang <code>ACCEPTED</code>, hệ thống tự động sinh một <code>TaskDocument</code> đẩy vào Task Backlog của Workspace.</li></ul></li><li><strong><code>3.5.12 Update Request</code> (<code>Owner</code>, <code>Manager</code>, <code>Client</code>)</strong>: <ul><li>Người tạo chỉnh sửa tiêu đề, mô tả, hạn mong muốn hoặc tệp tham khảo khi yêu cầu đang ở trạng thái <code>PENDING</code>; ngay khi đã chuyển sang <code>IN_PROGRESS</code>, <code>ACCEPTED</code> hoặc <code>DENIED</code> thì nội dung yêu cầu bị khóa không cho sửa (<code>BR-32</code>).</li></ul></li><li><strong><code>3.5.13 Cancel Request</code> (<code>Owner</code>, <code>Manager</code>, <code>Client</code>)</strong>: <ul><li>Khi yêu cầu đang ở <code>PENDING</code>, người tạo có quyền hủy yêu cầu (<code>status = CANCELLED</code>, <code>BR-32</code>).</li></ul></li></ol><ul><li><strong>Hành vi ở chế độ <code>PERSONAL</code></strong>: Vì không có <code>Client</code>, mục <code>Yêu cầu Nội dung (/requests)</code> được ẩn khỏi Sidebar để tránh dư thừa; người dùng cá nhân tạo trực tiếp Task tại <code>/tasks</code>.</li></ul><hr><h2 id="_5-bang-tham-chieu-quy-tac-nghiep-vu-br-25-–-br-33" tabindex="-1">5. Bảng Tham chiếu Quy tắc Nghiệp vụ (<code>BR-25</code> – <code>BR-33</code>) <a class="header-anchor" href="#_5-bang-tham-chieu-quy-tac-nghiep-vu-br-25-–-br-33" aria-label="Permalink to &quot;5. Bảng Tham chiếu Quy tắc Nghiệp vụ (`BR-25` – `BR-33`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã BR</th><th style="text-align:left;">Tên Quy tắc</th><th style="text-align:left;">Quy định Ràng buộc Cụ thể</th><th style="text-align:left;">FR Áp dụng</th></tr></thead><tbody><tr><td style="text-align:center;"><code>BR-25</code></td><td style="text-align:left;"><strong>Sao chép Độc lập Gói Truyền thông</strong></td><td style="text-align:left;">Tùy chỉnh Gói dịch vụ trong một <code>Workspace</code> tạo bản sao điều khoản riêng trên <code>workspace_media_packages</code>, không bao giờ làm thay đổi <code>MediaPackage</code> mẫu gốc của <code>Agency</code>.</td><td style="text-align:left;"><code>3.5.1</code>–<code>3.5.3</code></td></tr><tr><td style="text-align:center;"><code>BR-26</code></td><td style="text-align:left;"><strong>Đồng thuận Nguyên tử 2 Bên (<code>Two-Party ACID Approval</code>)</strong></td><td style="text-align:left;">Ở chế độ <code>AGENCY</code>, gói dịch vụ chỉ đạt <code>APPROVED</code> khi cả <code>approved_by_agency_at</code> và <code>approved_by_client_at</code> đều khác <code>NULL</code>; bất kỳ chỉnh sửa nào lên điều khoản/số lượng sẽ tự động đặt lại chữ ký của bên đối diện về <code>NULL</code> trong cùng giao dịch PostgreSQL.</td><td style="text-align:left;"><code>3.5.3</code>, <code>3.5.4</code></td></tr><tr><td style="text-align:center;"><code>BR-27</code></td><td style="text-align:left;"><strong>Mở khóa Chiến dịch từ Gói Đã Duyệt</strong></td><td style="text-align:left;">Trong chế độ <code>AGENCY</code>, chỉ được khởi tạo và phê duyệt <code>MediaCampaign</code> khi <code>Workspace</code> đã có <code>WorkspaceMediaPackage</code> ở trạng thái <code>APPROVED</code> và tổng hạng mục chiến dịch không vượt trần gói.</td><td style="text-align:left;"><code>3.5.4</code>–<code>3.5.8</code></td></tr><tr><td style="text-align:center;"><code>BR-28</code></td><td style="text-align:left;"><strong>Lịch sử Phiên bản Chiến dịch (<code>CampaignVersion</code>)</strong></td><td style="text-align:left;">Mỗi lần cập nhật kế hoạch chiến dịch hoặc gửi phản hồi đàm phán đều lưu lại snapshot <code>campaign_versions</code> và sự kiện <code>campaign_review_events</code> để đối chiếu.</td><td style="text-align:left;"><code>3.5.6</code>, <code>3.5.7</code></td></tr><tr><td style="text-align:center;"><code>BR-29</code></td><td style="text-align:left;"><strong>Sinh Công việc Chống Trùng lặp (<code>Idempotent Deploy</code>)</strong></td><td style="text-align:left;">Khi phê duyệt triển khai chiến dịch (<code>3.5.8</code>), <code>campaign_deployments</code> sinh nguyên tử các <code>TaskDocument</code> và <code>Subtask</code> vai trò chuẩn trong MongoDB kèm khóa chống sinh trùng hạng mục.</td><td style="text-align:left;"><code>3.5.8</code></td></tr><tr><td style="text-align:center;"><code>BR-30</code></td><td style="text-align:left;"><strong>Nghiệm thu Chiến dịch &amp; Dọn Yêu cầu Treo</strong></td><td style="text-align:left;">Khi chiến dịch chuyển sang <code>COMPLETED</code> (<code>3.5.9</code>), hệ thống khóa tạo mới hạng mục trong chiến dịch đó và tự động chuyển các <code>Content Request</code> đang treo <code>PENDING</code> thuộc chiến dịch sang <code>CANCELLED</code>.</td><td style="text-align:left;"><code>3.5.7</code>, <code>3.5.9</code></td></tr><tr><td style="text-align:center;"><code>BR-31</code></td><td style="text-align:left;"><strong>Máy Trạng thái Yêu cầu Nội dung 1 Chiều</strong></td><td style="text-align:left;"><code>Content Request</code> tuân thủ chu trình <code>PENDING → IN_PROGRESS → ACCEPTED / DENIED</code> (hoặc <code>CANCELLED</code> từ <code>PENDING</code>); <code>DENIED</code> và <code>CANCELLED</code> là trạng thái kết thúc không thể mở lại.</td><td style="text-align:left;"><code>3.5.10</code>, <code>3.5.11</code></td></tr><tr><td style="text-align:center;"><code>BR-32</code></td><td style="text-align:left;"><strong>Khóa Sửa / Hủy Yêu cầu sau Tiếp nhận</strong></td><td style="text-align:left;">Người tạo chỉ được chỉnh sửa (<code>3.5.12</code>) hoặc hủy (<code>3.5.13</code>) khi yêu cầu còn ở <code>PENDING</code>; ngay khi <code>Manager</code>/<code>Owner</code> chuyển sang <code>IN_PROGRESS</code> thì nội dung yêu cầu gốc được khóa cố định.</td><td style="text-align:left;"><code>3.5.12</code>, <code>3.5.13</code></td></tr><tr><td style="text-align:center;"><code>BR-33</code></td><td style="text-align:left;"><strong>Tự động Khởi tạo Task khi Chấp thuận Yêu cầu</strong></td><td style="text-align:left;">Khi <code>Content Request</code> chuyển sang <code>ACCEPTED</code>, hệ thống tự động khởi tạo một <code>TaskDocument</code> liên kết mã yêu cầu và đồng bộ ngược trạng thái hoàn tất qua <code>content_request_completion_jobs</code>.</td><td style="text-align:left;"><code>3.5.11</code>, <code>3.6.1</code>, <code>3.6.2</code></td></tr></tbody></table><hr><h2 id="_6-anh-xa-thuc-the-co-so-du-lieu-postgresql-↔-mongodb" tabindex="-1">6. Ánh xạ Thực thể Cơ sở Dữ liệu (<code>PostgreSQL</code> ↔ <code>MongoDB</code>) <a class="header-anchor" href="#_6-anh-xa-thuc-the-co-so-du-lieu-postgresql-↔-mongodb" aria-label="Permalink to &quot;6. Ánh xạ Thực thể Cơ sở Dữ liệu (`PostgreSQL` ↔ `MongoDB`)&quot;">​</a></h2><ul><li><strong>PostgreSQL (<code>brandhub-business-service</code>)</strong>: <code>media_packages</code>, <code>workspace_media_packages</code>, <code>package_negotiation_events</code>, <code>media_campaigns</code>, <code>campaign_versions</code>, <code>campaign_review_events</code>, <code>campaign_deployments</code>, <code>content_request_completion_jobs</code> (xem <a href="./../database/schema/erd-entity-descriptions.html">ERD Entity Descriptions</a>).</li><li><strong>MongoDB (<code>brandhub-business-service</code>)</strong>: <code>content_requests</code>, <code>tasks</code>, <code>task_sections</code> (liên kết mềm về <code>media_campaigns.id</code> và <code>workspaces.id</code>).</li></ul>',28)])])}const y=t(n,[["render",a]]);export{u as __pageData,y as default};
